use atty::{self, Stream};
use clap::{crate_name, crate_version, App as ClapApp, AppSettings, Arg, ArgGroup, SubCommand};
use console::Term;
use once_cell::sync::Lazy;
use std::env;
use std::path::Path;

use crate::app::App;
use bat::{
    assets::HighlightingAssets,
    config::{Config, VisibleLines},
    error::*,
    line_range::{HighlightedLineRanges, LineRange, LineRanges},
    MappingTarget, PagingMode, SyntaxMapping, WrappingMode,
};

pub struct PagingSpec {
    interactive_output: bool,
    color_enabled: bool,
}

impl PagingSpec {
    pub fn from_terminal(interactive_output: bool) -> Self {
        PagingSpec {
            interactive_output,
            color_enabled: interactive_output && env::var_os("NO_COLOR").is_none(),
        }
    }

    fn no_paging_arg(&self) -> Arg<'static, 'static> {
        Arg::with_name("no-paging")
            .short("P")
            .long("no-paging")
            .alias("no-pager")
            .overrides_with("no-paging")
            .hidden(true)
            .hidden_short_help(true)
            .help("Alias for '--paging=never'")
    }
}

static VERSION: Lazy<String> = Lazy::new(|| {
    #[cfg(feature = "bugreport")]
    let git_version = bugreport::git_version!(fallback = "");
    #[cfg(not(feature = "bugreport"))]
    let git_version = "";

    if git_version.is_empty() {
        crate_version!().to_string()
    } else {
        format!("{} ({})", crate_version!(), git_version)
    }
});

pub fn build_app(interactive_output: bool) -> ClapApp<'static, 'static> {
    let spec = PagingSpec::from_terminal(interactive_output);
    let clap_color_setting = if spec.color_enabled {
        AppSettings::ColoredHelp
    } else {
        AppSettings::ColorNever
    };

    let mut app = ClapApp::new(crate_name!())
        .version(VERSION.as_str())
        .global_setting(clap_color_setting)
        .global_setting(AppSettings::DeriveDisplayOrder)
        .global_setting(AppSettings::UnifiedHelpMessage)
        .global_setting(AppSettings::HidePossibleValuesInHelp)
        .setting(AppSettings::ArgsNegateSubcommands)
        .setting(AppSettings::AllowExternalSubcommands)
        .setting(AppSettings::DisableHelpSubcommand)
        .setting(AppSettings::VersionlessSubcommands)
        .max_term_width(100)
        .about(
            "A cat(1) clone with wings.\n\n\
             Use '--help' instead of '-h' to see a more detailed version of the help text.",
        )
        .after_help(
            "Note: `bat -h` prints a short and concise overview while `bat --help` gives all \
                 details.",
        )
        .long_about("A cat(1) clone with syntax highlighting and Git integration.")
