pub fn subcommand_matches<S: AsRef<str>>(&self, name: S) -> Option<&ArgMatches<'a>> {
    if let Some(ref s) = self.subcommand {
        if s.name == name.as_ref() {
            return Some(&s.matches);
        }
    }
